import{_ as n,C as a,o as r,c as i,j as t,a as o,E as h,a7 as l}from"./chunks/framework.C4ZIv4ii.js";const c="/falconcms/screenshots/search-console.webp",d="/falconcms/screenshots/search-console-opportunities.webp",g="/falconcms/screenshots/search-console-content-plan.webp",p="/falconcms/screenshots/search-console-index.webp",u="/falconcms/screenshots/search-console-speed.webp",m="/falconcms/screenshots/editor-search-console.webp",_=JSON.parse('{"title":"Search Console","description":"","frontmatter":{},"headers":[],"relativePath":"guide/search-console.md","filePath":"guide/search-console.md","lastUpdated":1791833165000}'),w={name:"guide/search-console.md"},f={id:"search-console",tabindex:"-1"};function y(b,e,k,v,S,x){const s=a("Badge");return r(),i("div",null,[t("h1",f,[e[0]||(e[0]=o("Search Console ",-1)),h(s,{type:"warning",text:"Pro"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#search-console","aria-label":'Permalink to "Search Console <Badge type="warning" text="Pro" />"'},"​",-1))]),e[3]||(e[3]=l('<p>The <strong>Falcon Search Console</strong> plugin brings Google Search Console into FalconCMS. You get clicks, impressions, click-through rate and position for the whole site, for every page and for every search. You also get what to improve next, and each page&#39;s numbers right in its editor.</p><p>It ships with <a href="/falconcms/guide/pro.html">FalconCMS Pro</a> (1.1.0 or later) and needs FalconCMS 2.7.10 or later. Activate it under <strong>Plugins</strong>, then open <strong>Search Console</strong> in the admin menu.</p><div class="tip custom-block"><p class="custom-block-title">Read-only</p><p>The plugin reads from Google and never writes to your content. A post&#39;s SEO title, description and everything else stay exactly as you left them.</p></div><p><img src="'+c+'" alt="Search Console overview"></p><p><em>Clicks, impressions, CTR and position against the previous period, brand vs non-brand searches, and a chart marked on the days you published or changed something.</em></p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting&quot;">​</a></h2><p>The plugin connects with a Google <strong>service account</strong>: a key that belongs to your site, not to a person. The settings screen walks you through it in three steps, with a direct link for each one:</p><ol><li><strong>Create a key in Google Cloud.</strong> Create a project, turn on the <strong>Search Console API</strong>, create a service account (no roles are needed) and download its <strong>JSON</strong> key.</li><li><strong>Upload the key.</strong> Drag the <code>.json</code> file onto the settings screen. It is stored encrypted.</li><li><strong>Give it access in Search Console.</strong> Copy the service account&#39;s email, open your property in Search Console → <strong>Settings → Users and permissions → Add user</strong>, paste it and choose <strong>Restricted</strong>.</li></ol><p>The screen checks every few seconds and connects on its own as soon as Google lets the account in. It picks the matching property by itself, whether a domain property (<code>sc-domain:example.com</code>) or a URL-prefix one. If something is wrong, it says what, and links to the screen where to fix it (the API not enabled, no access yet, a broken key).</p><h2 id="keeping-the-numbers-current" tabindex="-1">Keeping the numbers current <a class="header-anchor" href="#keeping-the-numbers-current" aria-label="Permalink to &quot;Keeping the numbers current&quot;">​</a></h2><p>The plugin keeps a copy of your data so the reports open instantly:</p><ul><li><strong>16 months</strong> of daily totals, pages, countries and devices, and <strong>90 days</strong> of searches (queries).</li><li>New data is fetched <strong>every hour</strong> by the scheduler (<code>falcon:gsc-sync</code>), and again after anyone opens the report, so a host without cron stays current too.</li><li>Google&#39;s figures run two to three days behind, so the report ends on the newest day Google has.</li></ul><p>Use <strong>Sync now</strong> at the top of the report to fetch right away.</p><h2 id="the-report" tabindex="-1">The report <a class="header-anchor" href="#the-report" aria-label="Permalink to &quot;The report&quot;">​</a></h2><p>Pick a range (7 days, 28 days, 3 months, 16 months) and a search type (web, image, video, news, Discover). Every list can be filtered, sorted, exported to CSV, and drilled into: open a search to see the pages it shows, or a page to see its searches.</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Queries / Pages / Countries / Devices</strong></td><td>The usual Search Console breakdowns, with full country names and flags.</td></tr><tr><td><strong>Tracked keywords</strong></td><td>Searches you star, with their position over time.</td></tr><tr><td><strong>Opportunities</strong></td><td>What to work on next (see below).</td></tr><tr><td><strong>Content plan</strong></td><td>Pages losing ground over months, and content ideas (see below).</td></tr><tr><td><strong>SEO changes</strong></td><td>Every time an SEO title or description changed, with the traffic before and after.</td></tr><tr><td><strong>Appearance</strong></td><td>Rich results and other search appearances, per page.</td></tr><tr><td><strong>Speed</strong></td><td>Core Web Vitals for your top pages, with what to fix (see below).</td></tr><tr><td><strong>Index status</strong></td><td>Whether Google has indexed each page, and why not (URL Inspection).</td></tr><tr><td><strong>Sitemaps</strong></td><td>The sitemaps Google knows about, with errors and warnings.</td></tr></tbody></table><h3 id="opportunities" tabindex="-1">Opportunities <a class="header-anchor" href="#opportunities" aria-label="Permalink to &quot;Opportunities&quot;">​</a></h3><p><img src="'+d+'" alt="Opportunities"></p><p><em>Searches just off page one, pages seen but not clicked, pages losing clicks, and pages competing with each other.</em></p><ul><li><strong>Almost on page one:</strong> searches where you rank 8–20 with real demand. A better title, a section that answers the search, or a few internal links can move them up.</li><li><strong>Seen but not clicked:</strong> pages on page one that get far fewer clicks than their position usually earns. Rewrite the title and description.</li><li><strong>Losing clicks:</strong> pages that lost a third of their clicks against the previous period.</li><li><strong>Pages competing with each other:</strong> searches where two of your pages split the ranking. Keep the stronger one and link the other to it, or merge them.</li></ul><h3 id="content-plan" tabindex="-1">Content plan <a class="header-anchor" href="#content-plan" aria-label="Permalink to &quot;Content plan&quot;">​</a></h3><p><img src="'+g+'" alt="Content plan"></p><p><em>Pages losing ground with the likely reason, and searches you are shown for but have no page about.</em></p><ul><li><strong>Losing ground over months:</strong> pages with at least a quarter fewer clicks in the last 90 days than in the 90 before. Each comes with the likely reason, six months of clicks and when the page was last updated: <ul><li><strong>lost ranking:</strong> others now answer the search better;</li><li><strong>fewer searches:</strong> a season or a fading topic;</li><li><strong>fewer clicks per view:</strong> the result looks less appealing;</li><li><strong>no longer shown:</strong> check Index status.</li></ul></li><li><strong>Content ideas:</strong> searches Google shows your site for deep in the results (position 13 or lower) that no page title on your site covers. Variants of one search are grouped. <strong>Write a post</strong> opens a new post with the idea as its title.</li></ul><h3 id="index-status" tabindex="-1">Index status <a class="header-anchor" href="#index-status" aria-label="Permalink to &quot;Index status&quot;">​</a></h3><p><img src="'+p+'" alt="Index status"></p><p><em>Each page&#39;s index status from Google&#39;s URL Inspection, with the reason a page is not indexed.</em></p><p>Pages are inspected in small batches (Google allows a limited number per day), newest and most visited first. <strong>Inspect now</strong> in the editor checks one page straight away.</p><h3 id="speed" tabindex="-1">Speed <a class="header-anchor" href="#speed" aria-label="Permalink to &quot;Speed&quot;">​</a></h3><p><img src="'+u+'" alt="Speed"></p><p><em>Real-visitor Core Web Vitals and a Lighthouse score for the top pages, with the fixes that save the most time.</em></p><p>The top 20 pages by clicks are checked with Google&#39;s PageSpeed Insights. You can add a free PageSpeed API key in the plugin settings for a higher daily limit. For your own visitors&#39; speed, measured live, see <a href="/falconcms/guide/analytics.html#web-vitals">Web Vitals</a>.</p><h2 id="in-the-editor" tabindex="-1">In the editor <a class="header-anchor" href="#in-the-editor" aria-label="Permalink to &quot;In the editor&quot;">​</a></h2><p>Every page and post that has Search Console data shows a <strong>Google Search</strong> card under its SEO settings.</p><p><img src="'+m+'" alt="The Google Search card in the editor"></p><p><em>The page&#39;s index status, a search result check, pages it competes with, and its top searches.</em></p><ul><li><strong>Index status</strong>, with <strong>Inspect now</strong>.</li><li><strong>Search result check:</strong> how wide the title and description are against what Google shows, and which of the page&#39;s searches use words that are missing from the title.</li><li><strong>Competing pages:</strong> searches where another of your pages also ranks.</li><li><strong>Clicks, impressions, CTR and position</strong> for the last 28 days, and the top searches.</li></ul><p>The plugin also adds Google&#39;s view to the editor&#39;s <a href="/falconcms/guide/seo.html#keywords">Keywords</a> and <a href="/falconcms/guide/seo.html#internal-linking">Internal Linking</a> tabs.</p><h2 id="elsewhere-in-the-admin" tabindex="-1">Elsewhere in the admin <a class="header-anchor" href="#elsewhere-in-the-admin" aria-label="Permalink to &quot;Elsewhere in the admin&quot;">​</a></h2><ul><li><strong>Dashboard:</strong> a Search Console card with the last 28 days, and a link to the opportunities.</li><li><strong>Posts and Pages lists:</strong> each row&#39;s index status and clicks in the SEO column.</li><li><strong>SEO Audit:</strong> &quot;Not in Google&#39;s index&quot;, with Google&#39;s reason for each page.</li><li><strong>Alerts:</strong> a notice when a page&#39;s clicks drop sharply.</li><li><strong>Weekly email:</strong> a summary every Monday morning (<code>falcon:gsc-report</code>).</li></ul><h2 id="who-can-see-it" tabindex="-1">Who can see it <a class="header-anchor" href="#who-can-see-it" aria-label="Permalink to &quot;Who can see it&quot;">​</a></h2><p>Access is the <strong>Manage Search Console</strong> permission (<code>manage_search_console</code>), which you can give to any role under <strong>Users → Roles</strong>.</p>',42))])}const P=n(w,[["render",y]]);export{_ as __pageData,P as default};
